fn main() {
    let mut attributes = tauri_build::Attributes::new();
    println!("cargo:rerun-if-changed=resources/provenance.json");
    if let Ok(bytes) = std::fs::read("resources/provenance.json") {
        // Build provenance is generated by the ordinary resource assembler, not launch input.
        let value: serde_json::Value = serde_json::from_slice(&bytes).expect("Resource provenance");
        assert_eq!(
            value["version"].as_u64(),
            Some(2),
            "Reassemble v2 resources"
        );
        for (field, name) in [
            ("sourceFingerprint", "TRAINER_ORDINARY_SOURCE"),
            ("buildSourceFingerprint", "TRAINER_ORDINARY_BUILD_SOURCE"),
            ("buildContext", "TRAINER_ORDINARY_BUILD_CONTEXT"),
        ] {
            let identity = value[field].as_str().expect("Resource build identity");
            assert!(identity.len() == 64 && identity.bytes().all(|c| c.is_ascii_hexdigit()));
            println!("cargo:rustc-env={name}={identity}");
        }
    }
    // Legacy debug permission metadata stays debug-only. The supported result-only
    // permission is compiled but granted solely to a natively admitted exact origin.
    if std::env::var_os("CARGO_CFG_DEBUG_ASSERTIONS").is_some() {
        let directory = std::path::PathBuf::from(std::env::var_os("OUT_DIR").unwrap())
            .join("debug-permissions");
        std::fs::create_dir_all(&directory).unwrap();
        for (source, name) in [
            ("permissions/setup.toml", "setup.toml"),
            ("permissions/isolated.toml", "isolated.toml"),
            ("debug/smoke-permission.toml", "smoke.toml"),
        ] {
            println!("cargo:rerun-if-changed={source}");
            std::fs::copy(source, directory.join(name)).unwrap();
        }
        let pattern = Box::leak(format!("{}/*.toml", directory.display()).into_boxed_str());
        attributes = attributes
            .app_manifest(tauri_build::AppManifest::new().permissions_path_pattern(pattern));
    }
    tauri_build::try_build(attributes).expect("Native capability build");
}
